import json, os

workspace = "/home/USER/runs/paper/qwen-hpl-u1-turns/frozen/held-out/play/users/u083/system/state/workspace/programs"
with open(os.path.join(workspace, "task-ab3e8dda.json"), 'r') as f:
    data = json.load(f)

demo_input = data['task-ab3e8dda']['demo_input']
demo_output = data['task-ab3e8dda']['demo_output']

# The background color (most common non-pattern color)
BG = 6

def transform(grid):
    H, W = len(grid), len(grid[0])
    result = [[grid[r][c] for c in range(W)] for r in range(H)]

    for r in range(H):
        for c in range(W):
            if grid[r][c] == 3:
                ref_r, ref_c = H - 1 - r, W - 1 - c
                if grid[ref_r][ref_c] == 3:
                    # Both positions have 3 - use background
                    result[r][c] = BG
                else:
                    result[r][c] = grid[ref_r][ref_c]
    return result

demo_input = data['task-ab3e8dda']['demo_input']
demo_output = data['task-ab3e8dda']['demo_output']
transformed = transform(demo_input)

print("Transformed matches demo output?", transformed == demo_output)

if transformed != demo_output:
    mismatches = 0
    for r in range(16):
        for c in range(16):
            if transformed[r][c] != demo_output[r][c]:
                print(f"  Mismatch at ({r},{c}): got {transformed[r][c]}, expected {demo_output[r][c]}")
                mismatches += 1
    print(f"Total mismatches: {mismatches}")
else:
    print("All match! Rule found.")
